//! The airport table, parsed from the generated TSV at first use.
//!
//! The data file is generated by `research/tools/gen_aviation.py` and keeps the
//! upstream text of every retained field, so regenerating it is a plain diff
//! against the OurAirports CSV. It is parsed once, lazily, into [`Airport`]
//! values; the column order is defined in [`crate::col`] and must match the
//! generator's `FIELDS`.

use std::sync::OnceLock;

use crate::{Airport, col};

/// The table, embedded in the binary. Comments start with `#`.
const RAW: &str = include_str!("../data/airports.tsv");

fn parse() -> Vec<Airport> {
    let mut out = Vec::new();
    for line in RAW.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let fields: Vec<&'static str> = line.split('\t').collect();
        assert_eq!(
            fields.len(),
            col::COUNT,
            "generated row has {} fields, expected {}",
            fields.len(),
            col::COUNT
        );
        out.push(Airport::from_fields(&fields));
    }
    out
}

/// Every airport in the table, in `ident` order.
pub(crate) fn all() -> &'static [Airport] {
    static TABLE: OnceLock<Vec<Airport>> = OnceLock::new();
    TABLE.get_or_init(parse)
}
